// Única fuente de verdad sobre disponibilidad. Devuelve también la config para que nadie más la lea.
const inp = $('Entrada').first().json;
const desde = String(inp.fecha || '');
const hasta = String(inp.fecha_hasta || '') || desde;
const personas = Number(inp.personas);
const ignorarVentana = inp.ignorar_anticipacion === true || inp.ignorar_anticipacion === 'true';
const cfg = {};
for (const it of $('Leer config').all()) { if (it.json.clave) cfg[it.json.clave] = String(it.json.valor); }
const tz = cfg.zona_horaria || 'America/Montevideo';
const franjas = String(cfg.franjas || '9h-10h-11h-13h-14h-15h-16h').split('-').map(function (s) { return parseInt(s); });
const dur = parseInt(cfg.duracion_min || '60');
const minH = parseInt(cfg.anticipacion_min_horas || '24');
const maxD = parseInt(cfg.anticipacion_max_dias || '30');
// Si existe anticipacion_max_dias_habiles, la ventana se cuenta en días hábiles (gana sobre anticipacion_max_dias).
const maxHab = cfg.anticipacion_max_dias_habiles ? parseInt(cfg.anticipacion_max_dias_habiles) : null;
const tope = parseInt(cfg.tope_personas || '50');
// Días hábiles desde config, por ejemplo "lun-vie" o "lun,mie,vie".
const MAPA = { lun: 1, mar: 2, mie: 3, 'mié': 3, jue: 4, vie: 5, sab: 6, 'sáb': 6, dom: 7 };
const habiles = new Set();
for (const parte of String(cfg.dias_habiles || 'lun-vie').toLowerCase().split(',')) {
  const [ini, fin] = parte.trim().split('-');
  const x = MAPA[ini], y = fin ? MAPA[fin] : MAPA[ini];
  if (x && y) for (let k = x; k <= y; k++) habiles.add(k);
}
if (!habiles.size) [1, 2, 3, 4, 5].forEach(function (k) { habiles.add(k); });
// Feriados desde config: fechas aaaa-mm-dd separadas por coma. No se ofrecen ni cuentan como días hábiles.
const feriados = new Set(String(cfg.feriados || '').split(',').map(function (s) { return s.trim(); }).filter(function (s) { return /^\d{4}-\d{2}-\d{2}$/.test(s); }));
const out = { fecha: desde, fecha_hasta: hasta, personas: personas, disponible: false, motivo: null, explicacion: null, opciones: [], slots_libres: [], dias: [], cfg: cfg };
const re = /^\d{4}-\d{2}-\d{2}$/;
if (!re.test(desde) || !re.test(hasta)) { out.motivo = 'fecha_invalida'; out.explicacion = 'No entendí la fecha: necesito un día concreto (por ejemplo 21/10).'; return [{ json: out }]; }
if (!(personas >= 1) || personas > tope) { out.motivo = 'personas_fuera_de_rango_max_' + tope; out.explicacion = personas >= 1 ? 'El máximo por reserva es de ' + tope + ' personas. La fecha no es el problema: el inconveniente es la cantidad. Para más de ' + tope + ' personas no se puede reservar por este chat.' : 'Necesito la cantidad de personas (un número entre 1 y ' + tope + ').'; return [{ json: out }]; }
const d0 = DateTime.fromISO(desde, { zone: tz }).startOf('day');
const d1 = DateTime.fromISO(hasta, { zone: tz }).startOf('day');
if (d1 < d0 || d1.diff(d0, 'days').days > 20) { out.motivo = 'rango_invalido_max_21_dias'; out.explicacion = 'Puedo consultar hasta 21 días seguidos por vez; elegí un rango más corto.'; return [{ json: out }]; }
const now = DateTime.now().setZone(tz);
// Último momento reservable. Con días hábiles: fin del N-ésimo día hábil contando desde mañana.
let limite = now.plus({ days: maxD });
let ventana = maxD + '_dias';
if (maxHab) {
  let dh = now.startOf('day'), n = 0;
  while (n < maxHab) { dh = dh.plus({ days: 1 }); if (habiles.has(dh.weekday) && !feriados.has(dh.toISODate())) n++; }
  limite = dh.endOf('day');
  ventana = maxHab + '_dias_habiles';
}
out.reservable_hasta = limite.toISODate();
const ocupados = [];
for (const e of $input.all().map(function (i) { return i.json; })) {
  if (!e || !e.start) continue;
  if (e.status === 'cancelled') continue;
  if (e.start.dateTime) ocupados.push([DateTime.fromISO(e.start.dateTime).toMillis(), DateTime.fromISO(e.end.dateTime).toMillis()]);
  else ocupados.push([DateTime.fromISO(e.start.date, { zone: tz }).toMillis(), DateTime.fromISO(e.end.date, { zone: tz }).toMillis()]);
}
for (let d = d0; d <= d1; d = d.plus({ days: 1 })) {
  // dia_semana va calculado acá para que el modelo no tenga que deducirlo (se equivocaba).
  const dia = { fecha: d.toISODate(), dia_semana: d.setLocale('es').toFormat("cccc d 'de' LLLL"), slots_libres: [], motivo: null, explicacion: null };
  if (!habiles.has(d.weekday)) { dia.motivo = d.weekday > 5 ? 'fin_de_semana' : 'dia_no_habil'; out.dias.push(dia); continue; }
  if (feriados.has(d.toISODate())) { dia.motivo = 'feriado'; out.dias.push(dia); continue; }
  let antes = 0, despues = 0, ocupadas = 0;
  for (const h of franjas) {
    const ini = d.set({ hour: h, minute: 0 });
    const fin = ini.plus({ minutes: dur });
    if (!ignorarVentana && ini < now.plus({ hours: minH })) { antes++; continue; }
    if (!ignorarVentana && ini > limite) { despues++; continue; }
    const a = ini.toMillis(), b = fin.toMillis();
    if (!ocupados.some(function (x) { return a < x[1] && b > x[0]; })) dia.slots_libres.push(ini.toFormat('HH:mm'));
    else ocupadas++;
  }
  if (!dia.slots_libres.length) {
    if (despues === franjas.length) dia.motivo = 'mas_de_' + ventana + '_de_anticipacion';
    else if (antes === franjas.length) dia.motivo = 'menos_de_' + minH + '_horas_de_anticipacion';
    else dia.motivo = 'sin_cupo';
  }
  out.dias.push(dia);
}
// Explicación en castellano por día, lista para que el agente la repita tal cual.
const ultimo = limite.setLocale('es').toFormat("cccc d 'de' LLLL");
for (const x of out.dias) {
  if (x.slots_libres.length) continue;
  if (x.motivo === 'feriado') x.explicacion = 'El ' + x.dia_semana + ' es feriado y el laboratorio no recibe visitas.';
  else if (x.motivo === 'fin_de_semana' || x.motivo === 'dia_no_habil') x.explicacion = 'El ' + x.dia_semana + ' no hay visitas: se reciben de lunes a viernes.';
  else if (String(x.motivo).indexOf('mas_de_') === 0) x.explicacion = 'El ' + x.dia_semana + ' todavía no se puede reservar: se reserva con hasta ' + (maxHab ? maxHab + ' días hábiles' : maxD + ' días') + ' de anticipación (el último día posible hoy es el ' + ultimo + ').';
  else if (String(x.motivo).indexOf('menos_de_') === 0) x.explicacion = 'El ' + x.dia_semana + ' ya no llega a las ' + minH + ' horas de anticipación que necesitamos para organizar la visita.';
  else x.explicacion = 'El ' + x.dia_semana + ' ya no quedan horarios libres.';
}
// Solo los días con horarios: es lo único que el agente debe ofrecer.
out.opciones = out.dias.filter(function (x) { return x.slots_libres.length > 0; }).map(function (x) { return { fecha: x.fecha, dia_semana: x.dia_semana, horarios: x.slots_libres }; });
out.reservable_hasta_texto = ultimo;
out.slots_libres = out.dias[0].slots_libres;
out.disponible = out.dias.some(function (x) { return x.slots_libres.length > 0; });
if (!out.disponible) out.motivo = out.dias.length === 1 ? out.dias[0].motivo : 'sin_cupo_en_el_rango';
return [{ json: out }];
